import UIKit

class SettingsViewController: BaseViewController {
    override func viewDidLoad() { super.viewDidLoad(); title = "Settings"; stack.addArrangedSubview(heading("Settings", subtitle: "Tune Blockside for your device.")); let theme = ActionButton(Preferences.dark ? "Switch to Light Theme" : "Switch to Dark Theme", color: UIColor(white: 0.32, alpha: 1)); theme.addTarget(self, action: #selector(toggleTheme), for: .touchUpInside); stack.addArrangedSubview(theme); stack.addArrangedSubview(card("Storage", body: "\(prettySize(LibraryStore.shared.sizeBytes())) used by imported library files. Remove items from Library to free space.", icon: "▤")); stack.addArrangedSubview(card("Downloads", body: "Downloads are stored in the app's local library. Large downloads may use significant storage and mobile data.", icon: "↓")); stack.addArrangedSubview(card("Language", body: "Language follows the device setting. Current interface language: English.", icon: "文")); stack.addArrangedSubview(card("Notifications", body: "No background notifications are configured. Downloads run while the app remains active.", icon: "♧")); stack.addArrangedSubview(card("About Blockside", body: "Version 1.0 · Built with Swift and UIKit for iOS 12 and later.\nLauncher interface and local content manager only; Minecraft game engine not included.", icon: "ⓘ")) }
    @objc private func toggleTheme() { Preferences.dark.toggle(); let nav = navigationController; let replacement = SettingsViewController(); nav?.setViewControllers([replacement], animated: false) }
}
